provider "google" {
  region = "europe-west1"
}

variable "bucket_name" {
  type        = string
  description = "Globally unique name for the Cloud Storage bucket."
  default     = "org-coldline-archive-europe-west1"
}

resource "google_storage_bucket" "coldline_bucket" {
  name          = var.bucket_name
  # The requirement explicitly specifies europe-west1, overriding the default asia-south1 policy.
  location      = "europe-west1"
  storage_class = "COLDLINE"

  # Enforce uniform IAM-based access control
  uniform_bucket_level_access = true

  # Satisfies org policy: explicit retention mechanism required for non-scratch buckets
  versioning {
    enabled = true
  }

  # Satisfies org policy: mandatory environment label for ownership and cost tracking
  labels = {
    environment = "prod"
  }
}

